arguments.command:
cat << 'EOF' > /app/output/viz.html
<!DOCTYPE html>
<html lang="en" class="theme-dark">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Event-Driven Architecture Panorama</title>

  <!-- Fonts -->
  <link href="/app/libs/fonts/inter.css" rel="stylesheet">

  <!-- Libraries -->
  <script src="/app/libs/html-to-image.js"></script>
  <script src="/app/libs/chart.js"></script>
  <script>Chart.defaults.animation = false;</script>
  <script src="/app/libs/mermaid.min.js"></script>

  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root { interpolate-size: allow-keywords; }

    /* ===== THEMES ===== */
    html.theme-dark {
      --bg: #0A0A0A; --surface: #141414; --surface-hover: #1C1C1C;
      --border: rgba(255,255,255,0.08);
      --text: #EDEDED; --text-secondary: #A1A1AA;
      --accent: #2563eb; --accent-secondary: #7c3aed;
      --positive: #10b981; --negative: #ef4444; --warning: #f59e0b;
    }
    html.theme-light {
      --bg: #FAFAF9; --surface: #FFFFFF; --surface-hover: #F5F5F4;
      --border: rgba(0,0,0,0.08);
      --text: #0f172a; --text-secondary: #64748b;
      --accent: #2563eb; --accent-secondary: #7c3aed;
      --positive: #059669; --negative: #e11d48; --warning: #d97706;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--bg); color: var(--text);
      line-height: 1.6; -webkit-font-smoothing: antialiased;
      letter-spacing: -0.01em; font-feature-settings: 'cv11', 'ss01';
      transition: background 0.3s, color 0.3s;
      overflow-x: hidden;
    }

    h1,h2,h3,h4,h5,h6 { color: var(--text); letter-spacing: -0.03em; line-height: 1.08; text-wrap: balance; }
    h1 { font-size: 3rem; font-weight: 700; margin-bottom: 0.5rem; }
    h2 { font-size: 2rem; font-weight: 600; margin-bottom: 1rem; }
    h3 { font-size: 1.5rem; font-weight: 500; margin-bottom: 0.75rem; }
    body, p, li, td, th, span, label { font-size: 1rem; font-weight: 400; color: var(--text); }
    .text-secondary { color: var(--text-secondary); font-size: 1.1rem;}

    /* ===== LAYOUT ===== */
    .dashboard-container {
      max-width: 1800px;
      margin: 0 auto;
      padding: 48px;
    }

    .card {
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 12px; padding: 32px;
      transition: box-shadow 0.2s ease;
      display: flex; flex-direction: column; height: 100%;
    }
    .card:hover {
      box-shadow: 0 0 0 1px var(--border), 0 8px 16px rgba(0,0,0,0.08);
    }

    .kpi-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
      margin-bottom: 32px;
    }

    .kpi-value {
      font-size: 3rem;
      font-weight: 700;
      color: var(--accent);
      margin-bottom: 4px;
      line-height: 1;
    }

    .architecture-section {
      margin-bottom: 32px;
    }

    .mermaid-container {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 40px;
      text-align: center;
      min-height: 600px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .charts-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 24px;
    }

    .chart-container {
      height: 360px;
      position: relative;
    }

    /* ===== ANIMATIONS ===== */
    @keyframes fadeInUp { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: translateY(0); } }
    .animate { animation: fadeInUp 0.6s ease-out both; }
    .delay-1 { animation-delay: 0.1s; }
    .delay-2 { animation-delay: 0.2s; }
    .delay-3 { animation-delay: 0.3s; }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation: none !important; transition: none !important; }
    }
    @media (max-width: 375px) { body { overflow-x: hidden; } }

    /* ===== MENU ===== */
    .viz-menu { position: fixed; top: 16px; right: 16px; z-index: 9999; }
    .viz-menu-toggle {
      width: 44px; height: 44px; border-radius: 12px; background: var(--surface); border: 1px solid var(--border);
      color: var(--text); cursor: pointer; display: flex; align-items: center; justify-content: center;
    }
    .viz-menu-dropdown {
      position: absolute; top: 52px; right: 0; min-width: 200px; background: var(--surface); border: 1px solid var(--border);
      border-radius: 12px; padding: 8px; opacity: 0; visibility: hidden; transform: translateY(-8px);
    }
    .viz-menu-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }
    .viz-menu-dropdown button {
      width: 100%; padding: 10px 14px; border: none; border-radius: 8px; background: transparent; color: var(--text); font-size: 14px;
      cursor: pointer; text-align: left; display: flex; align-items: center; gap: 10px;
    }
  </style>
</head>
<body>

  <div class="viz-menu">
    <button class="viz-menu-toggle" onclick="toggleMenu()">
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2"><line x1="3" y1="5" x2="17" y2="5"/><line x1="3" y1="10" x2="17" y2="10"/><line x1="3" y1="15" x2="17" y2="15"/></svg>
    </button>
    <div class="viz-menu-dropdown" id="vizMenuDropdown">
      <button onclick="cycleTheme()"><span id="themeIcon">🌙</span><span id="themeLabel">Dark</span></button>
      <button onclick="downloadImage()"><span>📥</span><span>Download PNG</span></button>
    </div>
  </div>

  <main id="main-content" class="dashboard-container">

    <header class="animate" style="margin-bottom: 40px;">
      <h1>Event-Driven Architecture Panorama</h1>
      <p class="text-secondary">Comprehensive view of microservice routing, validation, error-handling, and observability layers.</p>
    </header>

    <section class="kpi-grid animate delay-1">
      <div class="card">
        <div class="kpi-value">6</div>
        <h3>Microservices</h3>
        <p class="text-secondary">Producers and consumers</p>
      </div>
      <div class="card">
        <div class="kpi-value" style="color: var(--positive);">11</div>
        <h3>Kafka Topics</h3>
        <p class="text-secondary">Core & Dead Letter Queues</p>
      </div>
      <div class="card">
        <div class="kpi-value" style="color: var(--negative);">4</div>
        <h3>DLQ Pipelines</h3>
        <p class="text-secondary">Configured retry boundaries</p>
      </div>
      <div class="card">
        <div class="kpi-value" style="color: var(--warning);">33</div>
        <h3>Event Flows</h3>
        <p class="text-secondary">Async schema-validated streams</p>
      </div>
    </section>

    <section class="architecture-section animate delay-2">
      <h2 style="margin-bottom: 24px;">Architecture Topology</h2>
      <div class="mermaid-container">
        <div class="mermaid" id="architectureDiagram">
          graph TB
            classDef default font-family:Inter;
            classDef svc fill:#2563eb,stroke:#1d4ed8,stroke-width:2px,color:#fff,rx:8,ry:8
            classDef topic fill:#10b981,stroke:#047857,stroke-width:2px,color:#fff,rx:16,ry:16
            classDef dlq fill:#ef4444,stroke:#b91c1c,stroke-width:2px,color:#fff,rx:16,ry:16
            classDef schema fill:#f59e0b,stroke:#b45309,stroke-width:2px,color:#fff,rx:4,ry:4
            classDef obs fill:#8b5cf6,stroke:#6d28d9,stroke-width:2px,color:#fff,rx:4,ry:4

            subgraph Services ["Application Microservices"]
                O[Order Service]:::svc
                P[Payment Service]:::svc
                I[Inventory Service]:::svc
                S[Shipping Service]:::svc
                N[Notification Service]:::svc
                A[Analytics Service]:::svc
            end

            SR{{Schema Registry}}:::schema

            subgraph Hub ["Kafka Topics (Central Hub)"]
                TO[(orders.*)]:::topic
                TP[(payments.*)]:::topic
                TI[(inventory.*)]:::topic
                TS[(shipping.*)]:::topic
            end

            subgraph DLQs ["Dead Letter Queues"]
                DP[(dlq.payments)]:::dlq
                DI[(dlq.inventory)]:::dlq
                DS[(dlq.shipping)]:::dlq
                DN[(dlq.notification)]:::dlq
            end

            subgraph Observability ["Monitoring & Alerting"]
                PROM(Prometheus):::obs
                AM(Alertmanager):::obs
                GRAF(Grafana):::obs
                SLK(Slack/PagerDuty):::obs
            end

            %% Schema Validation
            O -.->|validate| SR
            P -.->|validate| SR
            I -.->|validate| SR
            S -.->|validate| SR
            N -.->|validate| SR
            A -.->|validate| SR

            %% Produce
            O -->|produce| TO
            P -->|produce| TP
            I -->|produce| TI
            S -->|produce| TS

            %% Consume
            TO -->|consume| P
            TO -->|consume| I
            TO -->|consume| N
            TO -->|consume| A

            TP -->|consume| S
            TP -->|consume| N
            TP -->|consume| A

            TI -->|consume| S
            TI -->|consume| A

            TS -->|consume| N
            TS -->|consume| A

            %% DLQ Paths
            linkStyle 30,31,32,33 stroke:#ef4444,stroke-width:3px,color:#ef4444;
            P ==>|max retries| DP
            I ==>|max retries| DI
            S ==>|max retries| DS
            N ==>|max retries| DN

            %% Observability Flows
            Services -.->|metrics| PROM
            Hub -.->|lag/throughput| PROM
            PROM -->|dashboards| GRAF
            PROM -->|rules| AM
            AM -->|critical/warning| SLK
        </div>
      </div>
    </section>

    <section class="charts-grid animate delay-3">
      <div class="card">
        <h3>Topic Throughput Constraints</h3>
        <p class="text-secondary" style="margin-bottom: 24px; font-size: 0.9rem;">Peak throughput (msg/sec) across core business topics</p>
        <div class="chart-container" role="img" aria-label="Bar chart showing topic throughput">
          <canvas id="throughputChart"></canvas>
        </div>
      </div>

      <div class="card">
        <h3>Consumer Recovery Strategy</h3>
        <p class="text-secondary" style="margin-bottom: 24px; font-size: 0.9rem;">Max allowed retries before routing to DLQ</p>
        <div class="chart-container" role="img" aria-label="Bar chart showing service retry configuration">
          <canvas id="retryChart"></canvas>
        </div>
      </div>
    </section>
  </main>

  <script>
    // Menu System
    function toggleMenu() { 
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open'); 
    }

    // Theme Management
    var currentTheme = 'dark';
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme('dark'); // Fixed to dark for consistent high-density technical screenshot

    // Chart.js Bulletproof Manager
    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') return null;
        try {
          if (this.charts.has(canvasId)) {
            this.charts.get(canvasId).destroy();
            this.charts.delete(canvasId);
          }
          var ctx = document.getElementById(canvasId);
          if (!ctx) return null;
          if (ctx.chart) { ctx.chart.destroy(); delete ctx.chart; }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) ctx.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(ctx, config);
          this.charts.set(canvasId, chart);
          return chart;
        } catch (error) {
          console.error('Chart init failed:', error);
          return null;
        }
      }
    };

    function getChartColors() {
      var s = getComputedStyle(document.documentElement);
      return {
        text: s.getPropertyValue('--text').trim(),
        textSecondary: s.getPropertyValue('--text-secondary').trim(),
        border: s.getPropertyValue('--border').trim(),
        accent: s.getPropertyValue('--accent').trim(),
        positive: s.getPropertyValue('--positive').trim(),
        negative: s.getPropertyValue('--negative').trim()
      };
    }

    function buildCharts() {
      var colors = getChartColors();

      // Chart 1: Throughput
      ChartManager.safeInit('throughputChart', {
        type: 'bar',
        data: {
          labels: ['orders.created', 'orders.updated', 'payments.completed', 'inventory.reserved', 'shipping.dispatched', 'payments.failed'],
          datasets: [{
            label: 'Peak Throughput (msg/sec)',
            data: [5000, 3000, 4000, 4500, 2000, 800],
            backgroundColor: colors.accent,
            borderRadius: 6
          }]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          plugins: {
            tooltip: { enabled: true, padding: 12, cornerRadius: 8 },
            legend: { labels: { color: colors.text, font: { family: 'Inter' } } }
          },
          scales: {
            y: { ticks: { color: colors.textSecondary }, grid: { color: colors.border } },
            x: { ticks: { color: colors.textSecondary }, grid: { display: false } }
          }
        }
      });

      // Chart 2: Retries
      ChartManager.safeInit('retryChart', {
        type: 'bar',
        data: {
          labels: ['Payment Service', 'Shipping Service', 'Inventory Service', 'Notification Service', 'Analytics Service'],
          datasets: [{
            label: 'Max Retries',
            data: [5, 4, 3, 2, 0],
            backgroundColor: colors.positive,
            borderRadius: 6
          }]
        },
        options: {
          indexAxis: 'y',
          responsive: true, maintainAspectRatio: false,
          plugins: {
            tooltip: { enabled: true, padding: 12, cornerRadius: 8 },
            legend: { labels: { color: colors.text, font: { family: 'Inter' } } }
          },
          scales: {
            x: { ticks: { color: colors.textSecondary, stepSize: 1 }, grid: { color: colors.border } },
            y: { ticks: { color: colors.textSecondary }, grid: { display: false } }
          }
        }
      });
    }

    function onThemeChange() { setTimeout(buildCharts, 50); }

    // Initialize after load
    window.addEventListener('load', function() {
      mermaid.initialize({
        startOnLoad: true,
        theme: 'base',
        fontFamily: 'Inter',
        flowchart: { curve: 'basis', padding: 20 },
        themeVariables: {
          primaryColor: '#141414',
          primaryTextColor: '#EDEDED',
          primaryBorderColor: '#333',
          lineColor: '#555',
          secondaryColor: '#1C1C1C',
          tertiaryColor: '#222'
        }
      });
      buildCharts();
    });
  </script>
</body>
</html>
EOF
